def min_text_length_after_abbreviation(n, words):
    from itertools import combinations

    def is_equal(seg1, seg2):
        return seg1 == seg2

    def get_abbreviation(seg):
        return ''.join(word[0].upper() for word in seg)

    min_length = len(words)
    for i, j in combinations(range(n + 1), 2):
        for k, l in combinations(range(n + 1), 2):
            if i < k < j < l:
                seg1 = words[i:j]
                seg2 = words[k:l]
                if is_equal(seg1, seg2):
                    new_text = words[:i] + [get_abbreviation(seg1)] + words[j:k] + [get_abbreviation(seg2)] + words[l:]
                    min_length = min(min_length, len(' '.join(new_text)))
    return min_length

